function splitTopLevel(tokens, pred) {
    const parts = [];
    let depth = 0;
    let partStart = 0;
    for (let i = 0; i < tokens.length; i++) {
        const token = tokens[i];
        if (token.type === TYPE.Function) depth++;
        else if (token.type === TYPE.LeftParenthesis) depth++;
        else if (token.type === TYPE.RightParenthesis) depth--;
        else if (depth === 0 && pred(token)) {
            parts.push([partStart, i]);
            partStart = i + 1;
        }
    }
    parts.push([partStart, tokens.length]);
    return parts;
}
