function findTopLevelSlash(tokens, start, end) {
    let depth = 0;
    for (let i = start; i < end; i++) {
        const t = tokens[i];
        if (t.type === TYPE.Function) depth++;
        else if (t.type === TYPE.LeftParenthesis) depth++;
        else if (t.type === TYPE.RightParenthesis) depth--;
        else if (depth === 0 && t.type === TYPE.Delim && t.value === '/') return i;
    }
    return -1;
}
