function renderRange(tokens, start, end) {
    let result = '';
    for (let i = start; i < end; i++) {
        if (i > start) {
            const prev = tokens[i - 1];
            const current = tokens[i];
            const needSpace =
                prev.type !== TYPE.Function &&
                !(prev.type === TYPE.Delim && prev.value === '(') &&
                !(current.type === TYPE.Delim && current.value === ')');
            if (needSpace) result += ' ';
        }
        result += tokens[i].value;
    }
    return result;
}
