export function compressShorthand(lexer, propertyName, longhands) {
    if (longhands === null || typeof longhands !== 'object') return null;
    const shorthand = getShorthand(lexer, propertyName);
    if (!shorthand) return null;

    const values = [];
    for (const name of shorthand.longhands) {
        const value = longhands[name];
        if (value === undefined || value === null || typeof value === 'object') return null;
        const str = String(value).trim();
        if (str === '') return null;
        values.push(str);
    }

    const allCssWide = values.every(value => isCssWideValue(lexer, value) !== false);
    if (allCssWide) {
        const first = values[0].toLowerCase();
        if (values.every(value => value.toLowerCase() === first)) return values[0];
        return null;
    }

    let result = null;
    switch (shorthand.kind) {
        case 'distribution': result = compress4(values); break;
        case 'radius': result = compressRadius(values); break;
        case 'broadcast': result = areAllEqual(values) ? values[0] : null; break;
        case 'pair': result = values[0].toLowerCase() === values[1].toLowerCase() ? values[0] : values[0] + ' ' + values[1]; break;
        case 'components': result = values.join(' '); break;
        case 'layers': result = compressLayers(values); break;
        case 'font': result = `${values[0]} ${values[1]} ${values[2]} ${values[3]} ${values[4]}/${values[5]} ${values[6]}`; break;
    }

    if (result === null || result === '') return null;
    if (!lexer.matchProperty(propertyName, result).matched) return null;
    return result;
}
