function compressLayers(values) {
    const [image, position, size, repeat, origin, clip, attachment, color] = values;
    const lists = [image, position, size, repeat, origin, clip, attachment].map(splitCommaList);
    const colorList = splitCommaList(color);
    const layers = lists[0].length;
    if (lists.some(list => list.length !== layers) || colorList.length !== 1) return null;
    const result = [];
    for (let i = 0; i < layers; i++) {
        const components = [
            lists[0][i],
            lists[1][i] + '/' + lists[2][i],
            lists[3][i],
            lists[4][i],
            lists[5][i],
            lists[6][i]
        ];
        if (i === layers - 1) components.push(colorList[0]);
        result.push(components.join(' '));
    }
    return result.join(', ');
}

function splitCommaList(value) {
    const tokens = tokenizeValue(value);
    return splitTopLevel(tokens, isComma)
        .map(([start, end]) => renderRange(tokens, start, end))
