```js
function collectPropertyRefs(node, refs) {
    if (!node || typeof node !== 'object') return refs;
    if (Array.isArray(node)) {
        for (const item of node) collectPropertyRefs(item, refs);
        return refs;
    }
    if (node.type === 'Property' && refs.indexOf(node.name) === -1) refs.push(node.name);
    if (Array.isArray(node.terms)) {
        for (const term of node.terms) collectPropertyRefs(term, refs);
    }
    if (node.term) collectPropertyRefs(node.term, refs);
    return refs;
}
```
