function getShorthand(lexer, propertyName) {
    const property = lexer.getProperty(propertyName);

    if (!property) {
        return null;
    }

    const known = KNOWN_SHORTHANDS[property.name];

    if (known) {
        return known;
    }

    const ast = property.syntax;

    if (!ast) {
        return null;
    }

    const refs = collectPropertyRefs(ast, []);

    if (!refs.length) {
        return null;
    }

    const top = ast.type === 'Group'
        ? ast
        : { type: 'Group', combinator: ' ', terms: [ast] };

    if (top.type !== 'Group') {
        return null;
    }

    // <a> || <b> || ... — components which can occur in any order
    if (top.combinator === '||') {
        const allRefs = top.terms.every(
            term => term.type === 'Property' && refs.indexOf(term.name) !== -1
        );
        const keywords = top.terms
            .filter(term => term.type === 'Keyword')
            .map(term => term.name.toLowerCase());

        if (allRefs && top.terms.length === refs.length) {
            // <a> || <b> || ... — components which can occur in any order
            //
            // for list-style, the keywords `inside`/`outside` are reserved for
            // the position, so the position is matched before the type
            if (property.name === 'list-style') {
                return {
                    kind: 'components',
                    longhands: refs,
                    matchOrder: ['list-style-position', 'list-style-type', 'list-style-image']
                };
            }

            return { kind: 'components', longhands: refs };
        }

        // none | [ <a> <b>? || <c> ] — components plus a standalone keyword
        // (e.g. flex: none)
        const nonKeywords = top.terms.filter(term => term.type !== 'Keyword');

        if (
            keywords.length &&
            refs.length &&
            nonKeywords.length === 1 &&
            nonKeywords[0].type === 'Group'
        ) {
            return { kind: 'components', longhands: refs, keywords };
        }
    }

    if (top.combinator !== ' ') {
        return null;
    }

    const unwrap = term => (term.type === 'Multiplier' ? term.term : term);

    // <a> <b>? (or <a>? <b>) — a pair: a single value applies to both longhands,
    // otherwise the first value goes to the first longhand and the second to the second
    if (top.terms.length === 2 && refs.length === 2) {
        const first = unwrap(top.terms[0]);
        const second = unwrap(top.terms[1]);

        if (first && second && first.type === 'Property' && second.type === 'Property') {
            return {
