function expandComponents(lexer, shorthand, tokens) {
    const consumed = new Array(tokens.length).fill(false);
    const result = Object.create(null);
    const order = shorthand.matchOrder || shorthand.longhands;

    for (const name of order) {
        const graph = longhandGraph(lexer, name);

        if (!graph) {
            return null;
        }

        const best = findBestLongest(makeMatcher(lexer, graph, tokens), consumed);

        if (best) {
            result[name] = renderRange(tokens, best.start, best.end);

            for (let k = best.start; k < best.end; k++) {
                consumed[k] = true;
            }
        } else {
            result[name] = initialValue(name);
        }
    }

    // when some tokens were not claimed by any longhand the value can not be decomposed
    // except a standalone keyword alternative (e.g. `flex: none`)
    const unconsumed = [];

    for (let k = 0; k < tokens.length; k++) {
        if (!consumed[k]) {
            unconsumed.push(k);
        }
    }

    if (unconsumed.length) {
        if (
            shorthand.keywords &&
            unconsumed.length === 1 &&
            tokens[unconsumed[0]].type === TYPE.Ident &&
            shorthand.keywords.indexOf(tokens[unconsumed[0]].value.toLowerCase()) !== -1
        ) {
            return result;
        }

        return null;
    }

    return result;
}
