+    if (parsed.some(part => part === null)) {
+        return null;
+    }
+
+    if (parsed.every(part => part[1] === null)) {
+        return compress4(values);
+    }
+
+    return (
+        compress4(parsed.map(part => part[0])) +
+        ' / ' +
+        compress4(parsed.map(part => part[1] || part[0]))
+    );
+}
+
+function compressLayers(values) {
+    const lists = values.slice(0, 7).map(splitCommaList);
+    const colorList = splitCommaList(values[7]);
+    const layers = lists[0].length;
+
+    if (lists.some(list => list.length !== layers) || colorList.length !== 1) {
+        return null;
+    }
+
+    const result = [];
+
+    for (let i = 0; i < layers; i++) {
+        const components = [
+            lists[0][i],
+            lists[1][i] + '/' + lists[2][i],
+            lists[3][i],
+            lists[4][i],
+            lists[5][i],
+            lists[6][i]
+        ];
+
+        if (i === layers - 1) {
+            components.push(colorList[0]);
+        }
+
+        result.push(components.join(' '));
+    }
+
+    return result.join(', ');
+}
+
+export function compressShorthand(lexer, propertyName, longhands) {
+    if (longhands === null || typeof longhands !== 'object') {
+        return null;
+    }
+
+    const shorthand = getShorthand(lexer, propertyName);
+
+    if (!shorthand) {
+        return null;
+    }
+
+    const values = [];
+
+    for (const name of shorthand.longhands) {
+        const value = longhands[name];
