+        return null;
+    }
+
+    let result;
+
+    switch (shorthand.kind) {
+        case 'distribution':
+            result = compress4(values);
+            break;
+        case 'radius':
+            result = compressRadius(values);
+            break;
+        case 'broadcast':
+            result = allEqualCaseInsensitive(values) ? values[0] : null;
+            break;
+        case 'pair':
+            result = values[0].toLowerCase() === values[1].toLowerCase()
+                ? values[0]
+                : values[0] + ' ' + values[1];
+            break;
+        case 'components':
+            result = values.join(' ');
+            break;
+        case 'layers':
+            result = compressLayers(values);
+            break;
+        case 'font':
+            result =
+                values[0] + ' ' +
+                values[1] + ' ' +
+                values[2] + ' ' +
+                values[3] + ' ' +
+                values[4] + '/' + values[5] + ' ' +
+                values[6];
+            break;
+    }
+
+    if (result === null || result === '') {
+        return null;
+    }
+
+    // the result must be a valid value for the shorthand
+    if (!lexer.matchProperty(propertyName, result).matched) {
+        return null;
+    }
+
+    return result;
+}

