+        ' / ' +
+        compress4(parsed.map(part => part[1] || part[0]))
+    );
+}
+
+function compressLayers(values) {
+    const lists = values.slice(0, 7).map(splitCommaList);
+    const colorList = splitCommaList(values[7]);
+    const layers = lists[0].length;
+
+    if (lists.some(list => list.length !== layers) || colorList.length !== 1) {
+        return null;
+    }
+
+    const result = [];
+
+    for (let i = 0; i < layers; i++) {
+        const components = [
+            lists[0][i],
+            lists[1][i] + '/' + lists[2][i],
+            lists[3][i],
+            lists[4][i],
+            lists[5][i],
+            lists[6][i]
+        ];
+
+        if (i === layers - 1) {
+            components.push(colorList[0]);
+        }
+
+        result.push(components.join(' '));
+    }
+
+    return result.join(', ');
+}
+
+export function compressShorthand(lexer, propertyName, longhands) {
+    if (longhands === null || typeof longhands !== 'object') {
+        return null;
+    }
+
+    const shorthand = getShorthand(lexer, propertyName);
+
+    if (!shorthand) {
+        return null;
+    }
+
+    const values = [];
+
+    for (const name of shorthand.longhands) {
+        const value = longhands[name];
+
+        if (value === undefined || value === null || typeof value === 'object') {
+            return null;
+        }
+
+        const str = String(value).trim();
+
+        if (str === '') {
+            return null;
+        }
+
+        values.push(str);
+    }
+
+    // when all longhands share the same CSS-wide keyword the keyword is the result
+    if (values.every(value => isCssWideValue(lexer, value) !== false)) {
+        if (allEqualCaseInsensitive(values)) {
+            return values[0];
+        }
+
+        return null;
+    }
+
+    let result;
+
+    switch (shorthand.kind) {
+        case 'distribution':
+            result = compress4(values);
+            break;
+        case 'radius':
+            result = compressRadius(values);
+            break;
+        case 'broadcast':
+            result = allEqualCaseInsensitive(values) ? values[0] : null;
+            break;
+        case 'pair':
+            result = values[0].toLowerCase() === values[1].toLowerCase()
+                ? values[0]
+                : values[0] + ' ' + values[1];
+            break;
+        case 'components':
+            result = values.join(' ');
+            break;
+        case 'layers':
+            result = compressLayers(values);
+            break;
+        case 'font':
+            result =
+                values[0] + ' ' +
+                values[1] + ' ' +
+                values[2] + ' ' +
+                values[3] + ' ' +
+                values[4] + '/' + values[5] + ' ' +
+                values[6];
+            break;
+    }
+
+    if (result === null || result === '') {
+        return null;
+    }
+
+    // the result must be a valid value for the shorthand
+    if (!lexer.matchProperty(propertyName, result).matched) {
+        return null;
+    }
+
+    return result;
+}
